import * as T from './three.module.js';
import {MAP_FEATURES} from './map-features.js?v=20261005-lighting1';
import {getAgent} from './agents-data.js?v=20261005-lighting1';
const V=(x=0,y=0,z=0)=>new T.Vector3(x,y,z),distance=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z);
export class MapInteractions {
 constructor(api){this.api=api;this.objects=[];this.group=new T.Group();api.scene.add(this.group);this.active=null;this.t=0;this.held=null;}
 dispose(){this.held=null;for(const o of this.objects){o.mesh.traverse(m=>{const i=this.api.walls.indexOf(m);if(i>=0)this.api.walls.splice(i,1);m.geometry?.dispose();m.material?.dispose();});}this.group.clear();this.objects=[];this.active=null;}
 attach(map){this.dispose();this.active=map;if(!map)return;this.features=MAP_FEATURES[map.key]||{};this.spawnCache={};for(const side of ['attack','defend']){const seed=this.features.spawn?.[side]||map.data.sourceSpawns?.[side]?.[0]||map.data.spawns[side][0];this.spawnCache[side]=this.formation(seed,side);}this.reset();}
 formation(seed,side){const n=this.active.navigation,p=n.safePoint(seed),points=[],pool=[];for(const a of n.areas){if(a.walkable===false)continue;const q=n.center(a),d=distance(q,p);if(d>9||Math.abs(q.floor-p.floor)>1.2||n.blocked(q.x,q.z,.4,q.floor))continue;pool.push({...q,d});}pool.sort((a,b)=>a.d-b.d);const target=side==='attack'?this.active.data.sites[0]:this.features.spawn?.attack||this.active.data.spawns.attack[0];for(const q of pool){if(points.some(a=>distance(a,q)<1.1))continue;points.push({...q,yaw:Math.atan2(q.x-target.x,q.z-target.z)});if(points.length===5)break;}if(points.length<5)throw Error('地图出生区不足五个独立可站立点：'+this.active.key+'/'+side);return points;}
 spawn(attacking,i){const list=this.spawnCache[attacking?'attack':'defend'];return {...list[i%list.length]};}
 surface(p){return this.active.navigation.safePoint(p);}
 add(kind,p,geo,color,options={}){const mesh=new T.Mesh(geo,new T.MeshStandardMaterial({color,roughness:.65,metalness:.35,emissive:color,emissiveIntensity:kind==='orb'?.5:0})),o={kind,mesh,...p,...options};mesh.position.set(p.x,p.floor+(kind==='orb'?.9:1.4),p.z);mesh.userData.mapUtility=o;this.group.add(mesh);this.objects.push(o);return o;}
 reset(){if(!this.active)return;const map=this.active,features=this.features;this.dispose();this.active=map;this.features=features;
  for(const d of features.doors||[]){const p=this.surface(d),o=this.add('door',p,new T.BoxGeometry(d.width,2.8,.2),d.rotating?0x778479:0x55716c,{...d,x:p.x,z:p.z,floor:p.floor,hp:500,open:0,target:0,rotation:d.yaw||0,cooldown:0});o.mesh.rotation.y=o.rotation;this.api.walls.push(o.mesh);const panelColor=d.rotating?0x626b62:0x354c4a;for(let k=0;k<7;k++){const panel=new T.Mesh(new T.BoxGeometry(d.width-.12,.025,.025),new T.MeshStandardMaterial({color:panelColor,roughness:.75}));panel.position.set(0,-1.1+k*.36,.115);o.mesh.add(panel);}if(d.rotating){const seal=new T.Mesh(new T.TorusGeometry(.65,.035,6,36),new T.MeshStandardMaterial({color:0x9cb2a5,emissive:0x1e6453,emissiveIntensity:.4}));seal.position.z=.13;o.mesh.add(seal);}const button=new T.Mesh(new T.BoxGeometry(.15,.22,.10),new T.MeshStandardMaterial({color:0x77dcc0,emissive:0x77dcc0,emissiveIntensity:.7}));button.position.set(d.width/2+.45,0,.3);o.mesh.add(button);o.button=button;}
  for(const d of features.breakables||[]){const p=this.surface(d),o=this.add('breakable',p,new T.BoxGeometry(d.width,2.8,.25),0xaebea2,{...d,x:p.x,z:p.z,floor:p.floor,hp:400,rotation:d.yaw||0});o.mesh.rotation.y=o.rotation;this.api.walls.push(o.mesh);}
  for(const d of features.orbs||[]){const p=this.surface(d);const o=this.add('orb',p,new T.SphereGeometry(.22,20,14),0x080f22,{progress:0,taken:false,name:'终极技能球'});o.mesh.material.emissive.setHex(0x202e4a);for(const a of [0,Math.PI/2]){const ring=new T.Mesh(new T.TorusGeometry(.26,.015,5,32),new T.MeshBasicMaterial({color:0xe9e8ff,transparent:true,opacity:.9}));ring.rotation.x=a;o.mesh.add(ring);}}
  for(const d of features.ropes||[]){const a=this.surface(d.a),b=this.surface(d.b),from=V(a.x,a.floor+1.8,a.z),to=V(b.x,b.floor+1.8,b.z),delta=to.clone().sub(from),mesh=new T.Mesh(new T.CylinderGeometry(.018,.018,delta.length(),5),new T.MeshBasicMaterial({color:0xffcd53}));mesh.position.copy(from.clone().add(to).multiplyScalar(.5));mesh.quaternion.setFromUnitVectors(V(0,1,0),delta.normalize());this.group.add(mesh);this.objects.push({kind:'rope',mesh,a,b,name:d.name,oneWay:!!d.oneWay});}
 }
 nearby(e){let best=null,dist=Infinity;for(const o of this.objects){if(o.taken||o.destroyed)continue;if(o.kind==='rope'){for(const [start,end]of (o.oneWay?[[o.a,o.b]]:[[o.a,o.b],[o.b,o.a]])){const d=distance(e,start);if(d<2&&d<dist&&Math.abs((e.floor||0)-start.floor)<3){dist=d;best={object:o,start,end};}}}else{const d=distance(e,o);if(d<3&&d<dist&&Math.abs((e.floor||0)-o.floor)<2){dist=d;best={object:o};}}}return best;}
 prompt(e){const n=this.nearby(e);if(!n)return '';const o=n.object;return o.kind==='orb'?'按住交互 / Z 获取终极技能点':o.kind==='rope'?'按交互 / Z 使用'+o.name:o.kind==='door'?`按交互 / Z ${o.rotating?'旋转':o.target?'关闭':'打开'}${o.name}`:o.kind==='breakable'?'射击摧毁'+o.name:'';}
 interact(e,held=false,dt=0){if(!e.alive||this.api.phase()!=='live')return false;const n=this.nearby(e);if(!n)return false;const o=n.object;
  if(o.kind==='orb'){if(held){if(this.held!==o){this.held=o;this.heldActor=e;o.progress=0;}o.progress+=dt;if(o.progress>=1){e.kit.points=Math.min(getAgent(e.agent).ultimateCost,e.kit.points+1);o.taken=true;o.mesh.visible=false;this.api.notify?.('获得 1 点终极技能点');this.held=null;}}return true;}
  if(held)return false;
  if(o.kind==='door'&&this.t>=o.cooldown){if(o.rotating){o.target=1;o.returnAt=this.t+10;o.cooldown=this.t+10;}else{o.target=o.target?0:1;o.cooldown=this.t+.8;}this.api.sound?.();return true;}
  if(o.kind==='rope'){const from=V(e.x,e.y??e.floor+1.65,e.z),to=V(n.end.x,n.end.floor+1.65,n.end.z);e.traversal={from,to,age:0,duration:Math.max(.5,from.distanceTo(to)/18)};return true;}return false;
 }
 hit(o,amount){if(o.hp<=0)return false;o.hp-=amount;if(o.hp<=0){o.destroyed=true;o.mesh.visible=false;const i=this.api.walls.indexOf(o.mesh);if(i>=0)this.api.walls.splice(i,1);}return true;}
 blocks(x,z,r,floor){return this.objects.some(o=>{if(!['door','breakable'].includes(o.kind)||o.destroyed||!o.rotating&&o.open>.9||Math.abs(o.floor-floor)>2.8)return false;const dx=x-o.x,dz=z-o.z,a=o.mesh.rotation.y;return Math.abs(dx*Math.cos(a)-dz*Math.sin(a))<o.width/2+r&&Math.abs(dx*Math.sin(a)+dz*Math.cos(a))<.15+r;});}
 tick(dt,actors){this.t+=dt;if(this.held&&(!this.api.holding?.()||!this.heldActor?.alive||this.nearby(this.heldActor)?.object!==this.held)){this.held.progress=0;this.held=null;}for(const o of this.objects){if(o.kind==='door'&&!o.destroyed){if(o.rotating&&o.returnAt&&this.t>=o.returnAt){o.target=0;o.returnAt=0;}const wanted=o.target,step=dt/(o.rotating?2:1.5);o.open+=Math.sign(wanted-o.open)*Math.min(step,Math.abs(wanted-o.open));if(o.rotating)o.mesh.rotation.y=o.rotation+o.open*Math.PI/2;else o.mesh.position.y=o.floor+1.4+o.open*3;}if(o.kind==='orb'&&!o.taken){o.mesh.rotation.y+=dt;o.mesh.position.y=o.floor+.9+Math.sin(this.t*2)*.07;}}for(const e of actors){const t=e.traversal;if(!t)continue;if(!e.alive){e.traversal=null;continue;}t.age+=dt;const p=t.from.clone().lerp(t.to,Math.min(1,t.age/t.duration));e.x=p.x;e.z=p.z;e.y=p.y;e.floor=p.y-1.65;if(t.age>=t.duration){e.floor=this.active.navigation.floorAt(e.x,e.z,e.floor)??e.floor;e.traversal=null;}}}
 buyBounds(attacking){const side=attacking?'attack':'defend',spawns=this.spawnCache[side],p=spawns[0];return [Math.min(...spawns.map(p=>p.x))-8,Math.min(...spawns.map(p=>p.z))-8,Math.max(...spawns.map(p=>p.x))+8,Math.max(...spawns.map(p=>p.z))+8];}
}
